ação interpessoal.","certainty":"adjudicated_high"},{"uri":"http://data.europa.eu/esco/skill/35f1dcdc-577f-46c6-96d9-6c7a64501de9","category":"H2","reason":"Equipamento de laboratório consiste em ferramentas e instrumentos concretos de trabalho científico.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/35f1f02e-f1b9-44a2-92d3-032a16fe586e","category":"H1","reason":"Trabalhar com pacientes sob medicação exige contexto e conhecimento especializado de cuidados de saúde e fármacos.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/36065f25-3bbe-4a5c-a0fe-5623ad4b20df","category":"H3","reason":"Técnicas artesanais são métodos estruturados para conceber e produzir artefactos manuais.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/3606bf22-1987-4356-b8c4-13e89d8f6c69","category":"H3","reason":"Processar e interpretar dados de extração é uma técnica analítica aplicada a operações especializadas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/360bad99-6286-4db4-aefc-e3be77b5c978","category":"H4","reason":"Promover e vender seguros de viagem é uma atividade comercial estruturada no domínio dos seguros.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/360c095b-b086-4613-a909-c12469f50364","category":"H3","reason":"Inspecionar defeitos no vidro é um procedimento técnico de controlo de qualidade.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/360e089b-e317-4d28-b3f4-d22c6a6cd50c","category":"H3","reason":"Fundir metais para joalharia é um processo técnico de transformação e moldagem de materiais.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/360e1c45-d335-4a19-b717-e1932927a72b","category":"H4","reason":"Receber, verificar, armazenar e encaminhar matérias-primas é uma operação estruturada de logística e inventário.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/3625aaa5-84ab-43bc-98cf-82e21ffcea12","category":"H2","reason":"Assumir o controlo por pedais adicionais envolve operar equipamento concreto de um veículo.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/362e01a8-3f99-4d1a-96f7-ce69f9f7e39f","category":"H4","reason":"Disponibilizar equipamento de proteção é uma atividade organizada de gestão e distribuição de recursos de segurança.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/36359101-4488-4859-83a8-9600d9faf3f2","category":"H4","reason":"Envolver comunidades na gestão de áreas protegidas visa gerir relações com partes interessadas numa operação territorial.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/3635b5e3-bdaa-449e-ade4-2973e0a3aba6","category":"H3","reason":"Desenvolver registos de informações militares é um processo estruturado de análise e gestão de informação especializada.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/363e30cf-b3ec-4b3f-b02c-ac77a5902d15","category":"H4","reason":"Definir estratégias de importação e exportação é planeamento estratégico comercial.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/36404bb8-ecce-4afc-88bc-78ebd45c4b90","category":"H3","reason":"Prever problemas na estrada integra uma prática técnica de condução defensiva e segura.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/364b3628-c750-436a-8f5c-1a75dd5c6648","category":"H1","reason":"Acompanhar lançamentos de livros requer conhecimento atualizado do domínio editorial e literário.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/36500a31-3204-45b2-bf75-5cfe06d9cea2","category":"H3","reason":"Utilizar métodos de gestão térmica consiste em aplicar técnicas de engenharia para controlo térmico de sistemas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/3652c7df-362c-4b44-a193-52713c566106","category":"H3","reason":"Estilos de natação são técnicas estruturadas de execução motora no desporto.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/36543682-5f95-4cac-9eb8-8d9990b00820","category":"H4","reason":"Vender revestimentos para pavimentos e paredes é uma atividade comercial estruturada de vendas.","certainty":"high"}]$m82_json$::jsonb;
  v_found integer;
begin
  select count(distinct item.uri) into v_found
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification');
  if v_found <> jsonb_array_length(v_input) then
    raise exception 'M82_ESCO_MAPPING_MISMATCH: found %, expected %', v_found, jsonb_array_length(v_input);
  end if;
  if exists (
    select mapping.concept_id
    from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
    join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
    join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
    group by mapping.concept_id having count(distinct item.category)>1
  ) then raise exception 'M82_ESCO_CANONICAL_CLASS_CONFLICT'; end if;
  insert into public.knowledge_competency_classifications
    (concept_id, subgroup_id, version, taxonomy_version, method, provenance)
  select distinct on (concept.id)
    concept.id, subgroup.id,
    coalesce((select max(history.version)+1 from public.knowledge_competency_classifications history
      where history.concept_id=concept.id),1),
    'competency-taxonomy-2.0.0', 'ai_assisted',
    jsonb_build_object('source','ESCO','sourceVersion','1.2.1','sourceURI',item.uri,
      'sourceHash','1b5e5356d4037cdd5c938131b385b9059a1e5f256ca621e8372b6633ec9aea80',
      'classifierVersion','prisma-competency-classification-1.1.0',
      'model','gpt-5.6-terra', 'reason',item.reason,'certainty',item.certainty,
      'agreement','M8.2-1.0.0')
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification')
  join public.competency_subgroups subgroup on subgroup.code=item.category and subgroup.scope='global' and subgroup.status='active'
  where not exists (select 1 from public.knowledge_competency_classifications current_class
    where current_class.concept_id=concept.id and current_class.is_current)
  order by concept.id,item.uri;
end $m82$;
